update natural_english_private.catalogue set questions=questions || '{"native-227-v2-audio":{"type":"mc","answers":["兩人約好見面，對方卻沒有到。"],"options":["兩人約好見面，對方卻沒有到。","對方準時到並提早離開。","說話者臨時取消見面。","兩人碰巧在街上偶遇。"]},"native-227-v2-continue":{"type":"mc","answers":["We didn’t have dinner. He stood me up."],"options":["We bumped into each other by chance.","We didn’t have dinner. He stood me up.","It was great. He arrived early.","I stood him up because I forgot."]},"native-227-v2-detail":{"type":"mc","answers":["兩人約好單獨見面，我到場等候，他沒來也沒通知。"],"options":["他有到場，但提早離開了。","兩人約好單獨見面，我到場等候，他沒來也沒通知。","他缺席一場有二十人的公開講座。","他事前傳訊息說要改天。"]},"native-227-v2-repair":{"type":"mc","answers":["Sam stood me up."],"options":["Sam and I called it off beforehand.","Sam stood me up.","I stood Sam up.","We both arrived on time."]},"native-227-v2-final":{"type":"open","answers":["Chris stood me up. I waited at the entrance for forty minutes.","I waited outside the exhibition for forty minutes, but Chris stood me up.","Chris didn’t show up or text me, so I think he stood me up."],"options":[]}}'::jsonb where module='native-227';
