update natural_english_private.catalogue set questions=questions || '{"native-229-v2-audio":{"type":"mc","answers":["引擎突然停止運作。"],"options":["車窗玻璃裂開。","車輪在路口打滑，但引擎仍正常運作。","引擎突然停止運作。","輪胎慢慢漏氣。"]},"native-229-v2-detail":{"type":"mc","answers":["車子行進中突然失去引擎動力。"],"options":["踩油門時車沒有反應，但儀表板仍亮。","輪胎漏氣，車身慢慢偏向一邊。","冷氣停止吹風，但車仍能加速。","車子行進中突然失去引擎動力。"]},"native-229-v2-explain":{"type":"mc","answers":["停止運作的是引擎。"],"options":["車的輪胎爆了。","停止運作的是引擎。","壞的是車窗。","車子的電池已沒電。"]},"native-229-v2-scene":{"type":"mc","answers":["紅燈前車子忽然失去動力，需靠邊重啟。"],"options":["低速時引擎發出異響，但仍持續運作。","輪胎被釘刺中，胎壓逐漸下降。","紅燈前車子忽然失去動力，需靠邊重啟。","車門鎖失靈，但引擎運作正常。"]},"native-229-v2-final":{"type":"open","answers":["The engine stalled on the way to the airport. I pulled over safely and will call for help.","Sorry, the engine stalled. I’ve pulled over and am arranging roadside assistance.","My engine stalled, so I pulled over safely. I’ll update you after I call for help."],"options":[]}}'::jsonb where module='native-229';
