update natural_english_private.catalogue set questions=questions || '{"native-399-v2-audio":{"type":"mc","answers":["皮膚鼓起一個含液的小泡。"],"options":["皮膚鼓起一個含液的小泡。","皮膚長期變得厚硬。","腳跟有一片被磨紅的平面擦傷。","腳掌上有長期形成的硬繭。"]},"native-399-v2-explain":{"type":"mc","answers":["blister 是新起的泡；callus 是反覆摩擦後的厚皮。"],"options":["blister 是長期形成的乾硬皮。","callus 是當天出現的透明小泡。","兩詞都指同一種皮膚形狀。","blister 是新起的泡；callus 是反覆摩擦後的厚皮。"]},"native-399-v2-branch":{"type":"mc","answers":["Let me change shoes; these are rubbing the blister."],"options":["I’ll rest for a minute and then walk in these shoes again.","I’ll put the shoes back on and hope the rubbing stops.","Let me change shoes; these are rubbing the blister.","I’ll loosen the laces but keep walking in the same shoes."]},"native-399-v2-scene":{"type":"mc","answers":["水泡是新起的含液小泡；厚繭是長期摩擦形成的硬皮。"],"options":["水泡是新起的含液小泡；厚繭是長期摩擦形成的硬皮。","水泡是長期厚皮；厚繭是新起含液小泡。","兩者都只會出現在腳後跟。","兩者都只是皮膚表面發紅，沒有形狀差異。"]},"native-399-v2-repair":{"type":"open","answers":["It’s a blister, not a callus. The paddle rubbed my finger and left a little fluid-filled bump.","I’ve got a blister on my finger from rowing. It’s a new fluid-filled bubble, not thick skin.","That’s a blister from the paddle rubbing my finger; a callus would be hard thick skin."],"options":[]}}'::jsonb where module='native-399';
