update natural_english_private.catalogue set questions=questions || '{"native-416-v2-audio":{"type":"mc","answers":["走過出口時警報因他而響起。"],"options":["走過出口時警報因他而響起。","他關掉了已響的警報。","他測試店內的火警鐘。","警報安靜地保持關閉。"]},"native-416-v2-explain":{"type":"mc","answers":["使警報開始響。"],"options":["把警報聲調小。","把警報裝在出口。","請職員關閉警報。","使警報開始響。"]},"native-416-v2-branch":{"type":"mc","answers":["Of course. I have the receipt; perhaps a tag was left on."],"options":["Yes, but please throw away the receipt first.","I’ll go through the alarm again without checking anything.","Of course. I have the receipt; perhaps a tag was left on.","No, the alarm must be broken, so I’m leaving immediately."]},"native-416-v2-tone":{"type":"mc","answers":["I think I set off the alarm. Could we check whether a tag is still on this?"],"options":["The alarm rang; I’m taking an extra item as compensation.","I didn’t hear anything, so you must be mistaken.","I think I set off the alarm. Could we check whether a tag is still on this?","You forgot the tag, so this is entirely your fault."]},"native-416-v2-scene":{"type":"mc","answers":["已付款的外套仍有防盜扣，經過出口感應門時響鐘。"],"options":["已付款的外套仍有防盜扣，經過出口感應門時響鐘。","店裏有消防演習，警報在你到達前已響。","收銀台的電話鈴響了。","你按了停車場的尋車喇叭。"]},"native-416-v2-final":{"type":"open","answers":["I think I set off the security alarm. I paid for the book and can show you the receipt.","The alarm went off when I walked out. Could we check whether the security sticker is still on the book?","I may have set off the alarm because the tag is still attached. Here’s my receipt."],"options":[]}}'::jsonb where module='native-416';
